const iframe=document.querySelector("iframe"),storage=chrome.storage&&chrome.storage.local;window.addEventListener("message",(event=>{if(event.source!==iframe.contentWindow)return;const{type:type,key:key,value:value,id:id}=event.data||{};if("storage:get"===type){if(!storage)return;storage.get(key,(result=>{iframe.contentWindow.postMessage({type:"storage:get:result",id:id,value:result[key]},"*")}))}else if("storage:set"===type){if(!storage)return;storage.set({[key]:value},(()=>{iframe.contentWindow.postMessage({type:"storage:set:done",id:id},"*")}))}}));